/**
 * n8n Code node — "Render HTML"   (Offer Dispatch — Akay, dAYMAj6mZD3hTV4T)
 * Mode: Run Once for All Items
 * Added 2026-09-02, replacing the Anthropic "Style as HTML" node.
 *
 * SOURCE OF TRUTH: repo .claude/skills/offer-dispatch/n8n/render-html.js.
 * Edit the repo file, run `node test-nodes.cjs`, then paste — never edit here.
 *
 * WHY THIS EXISTS. From 2026-08-27 the HTML version of the offer was produced
 * by a call to claude-opus-5. In four working days that one node stopped the
 * dispatch outright three times (`temperature is deprecated` 400 on 28533, then
 * "credit balance is too low" on 29332, 29354 and 29365) and its output failed
 * the verbatim check on two of the four sends that did reach the model
 * (29315: a number the model invented; 29382: a `&middot;` entity). A formatter
 * has no business depending on a metered third-party API, and the approved text
 * has a fixed shape, so it is rendered here deterministically: no credentials,
 * no credits, no network, and the same input always gives the same HTML.
 *
 * CONTRACT — identical to the node it replaces:
 *   - input is the ALREADY-COMPOSED, already leak-checked body from Compose Email
 *   - output is { content: "<html…>" }, which is the shape Verify HTML reads
 *   - it adds NO words, NO numbers, NO links and NO images of its own. Only the
 *     approved text is emitted between tags, HTML-escaped. Verify HTML still runs
 *     after this node and still falls back to plain text if that ever fails.
 *   - the {{{FIRST_NAME|there}}} token is left intact for Build Sends
 *
 * Body shape (from Compose Email): paragraphs separated by blank lines. A
 * paragraph whose first line is free text and whose remaining lines all read
 * "Label: value" is a product block and is rendered as a card with a two-column
 * table. A paragraph made only of "Label: value" lines (Terms / Validity /
 * Lead time) is rendered as a bare two-column table. Everything else is a <p>.
 */

const composed = $('Compose Email').first().json;
const text = String(composed.bodyTemplate || '');

return [{ json: { content: renderHtml(text) } }];

function renderHtml(body) {
  const NAVY = '#1A202C', INK = '#2D3748', MUTED = '#4A5568', LINE = '#E2E8F0', ACCENT = '#2563EB', PAGE = '#F7FAFC';
  const FONT = "-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
  const LABEL = /^([A-Za-z][A-Za-z ]{1,30}): (.+)$/;

  const paragraphs = String(body).replace(/\r\n?/g, '\n').split(/\n{2,}/).map((p) => p.replace(/^\n+|\n+$/g, '')).filter(Boolean);

  const parts = paragraphs.map((p) => {
    const lines = p.split('\n');
    const labelled = lines.map((l) => l.match(LABEL));
    const restLabelled = lines.length > 1 && labelled.slice(1).every(Boolean);
    const allLabelled = labelled.every(Boolean);

    if (allLabelled) return factsTable(labelled);
    if (restLabelled && !labelled[0]) return productCard(lines[0], labelled.slice(1));
    return `<p style="margin:0 0 14px 0;">${lines.map(esc).join('<br>')}</p>`;
  });

  return [
    '<!DOCTYPE html>',
    '<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>',
    `<body style="margin:0;padding:0;background:${PAGE};">`,
    `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${PAGE};">`,
    '<tr><td align="center" style="padding:24px 12px;">',
    `<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#FFFFFF;border:1px solid ${LINE};border-radius:8px;">`,
    `<tr><td style="height:6px;background:${ACCENT};border-radius:8px 8px 0 0;font-size:0;line-height:0;">&nbsp;</td></tr>`,
    `<tr><td style="padding:24px 28px 12px 28px;font-family:${FONT};font-size:15px;line-height:1.5;color:${INK};">`,
    parts.join('\n'),
    '</td></tr></table></td></tr></table></body></html>',
  ].join('\n');

  function productCard(title, rows) {
    return [
      `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 14px 0;border:1px solid ${LINE};border-radius:6px;">`,
      `<tr><td style="padding:12px 16px;font-family:${FONT};">`,
      `<div style="font-size:16px;font-weight:600;color:${NAVY};margin:0 0 6px 0;">${esc(title)}</div>`,
      rowsTable(rows),
      '</td></tr></table>',
    ].join('');
  }

  function factsTable(rows) {
    return `<div style="margin:0 0 14px 0;font-family:${FONT};">${rowsTable(rows)}</div>`;
  }

  function rowsTable(rows) {
    const trs = rows.map((m) =>
      `<tr><td style="padding:2px 12px 2px 0;color:${MUTED};font-weight:600;white-space:nowrap;vertical-align:top;">${esc(m[1])}</td>` +
      `<td style="padding:2px 0;color:${NAVY};">${esc(m[2])}</td></tr>`
    ).join('');
    return `<table role="presentation" cellpadding="0" cellspacing="0" style="font-size:15px;line-height:1.5;">${trs}</table>`;
  }

  function esc(s) {
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }
}

/**
 * n8n Code node — "Build Sends"
 * Mode: Run Once for All Items
 *
 * SOURCE OF TRUTH: repo .claude/skills/offer-dispatch/n8n/build-sends.js.
 * Edit the repo file, run `node test-nodes.cjs`, then paste — never edit here.
 *
 * Fans the recipient list out into ONE ITEM PER RECIPIENT. Each send carries
 * `offerIds` (the full bundle, or a single-element array for a normal offer)
 * so Reconcile can log and later mark every bundle member.
 *
 * Updated 2026-08-27: sends multipart when Verify HTML approved an HTML body.
 * `text` is ALWAYS present and is the same approved plain text as before, so a
 * client that blocks HTML still gets a complete, readable offer. `html` is
 * added only when verification passed; the placeholder assertion below now
 * covers both bodies, since an unresolved token is just as wrong in markup.
 * The fully-formed Resend payload is built here rather than in the HTTP node's
 * expression so the html key can be omitted cleanly on the text-only path.
 *
 * Updated 2026-09-02: every send now carries `idempotencyKey`, which the HTTP
 * node passes to Resend as the `Idempotency-Key` header. The key is
 * "dispatch:<first offer id>:<client id>", stable across runs, so:
 *   - the node's own 3x retry can never deliver twice on a timeout after
 *     Resend had already accepted the message;
 *   - two overlapping runs of the same group (2026-09-01 had runs 29311 and
 *     29315 in flight at the same time) cannot mail the same client twice;
 *   - a re-queue after a partial send only reaches the clients who did not get
 *     it the first time. Resend keeps a key for 24 hours, so a deliberate
 *     re-send of the same offer to the same client must wait a day.
 * A replayed key returns the original message id, which Reconcile counts as
 * Sent — correct, the client has the email.
 */

const recipients = $('Build Recipients').first().json;
const email = $('Verify HTML').first().json;

if (!email.composed) {
  return [{ json: { halt: true, haltReason: email.haltReason } }];
}

const list = recipients.recipients || [];
if (list.length === 0) {
  return [{ json: { halt: true, haltReason: 'No eligible recipients — nothing to send' } }];
}

const FROM = 'Akay Irl Ltd <offers@akay.ie>';
const offerIds = (email.bundleOfferIds && email.bundleOfferIds.length) ? email.bundleOfferIds : [email.offerId];

const sends = list.map((r) => {
  const subject = resolveFirstName(email.subject, r.firstName);
  const textBody = resolveFirstName(email.bodyTemplate, r.firstName);
  const htmlBody = email.html ? resolveFirstName(email.html, r.firstName) : null;
  const headers = { 'List-Unsubscribe': `<${email.listUnsubscribe}>` };

  const payload = { from: FROM, to: [r.email], subject, text: textBody, headers };
  if (htmlBody) payload.html = htmlBody;

  return {
    json: {
      payload,
      idempotencyKey: idempotencyKeyFor(offerIds[0], r),
      from: FROM,
      to: [r.email],
      subject,
      text: textBody,
      html: htmlBody,
      headers,

      offerId: email.offerId,
      offerIds,
      clientId: r.clientId,
      clientName: r.clientName,
      clientEmail: r.email,
      recipientIndex: list.indexOf(r),
      recipientTotal: list.length,
    },
  };
});

const PLACEHOLDER = /\{\{\{[^}]*\}\}\}/;
const seenKeys = new Set();

for (const s of sends) {
  if (!Array.isArray(s.json.to) || s.json.to.length !== 1) {
    throw new Error(`Send payload for ${s.json.clientName} does not have exactly one recipient`);
  }
  if ('bcc' in s.json.payload || 'cc' in s.json.payload) {
    throw new Error('Send payload contains cc/bcc — one email per recipient is required');
  }
  if (PLACEHOLDER.test(s.json.text) || PLACEHOLDER.test(s.json.subject)) {
    throw new Error(`Unsubstituted placeholder left in message for ${s.json.clientName}`);
  }
  if (s.json.html && PLACEHOLDER.test(s.json.html)) {
    throw new Error(`Unsubstituted placeholder left in the HTML body for ${s.json.clientName}`);
  }
  if (!s.json.payload.text) {
    throw new Error(`Send payload for ${s.json.clientName} has no plain-text body`);
  }
  if (!s.json.idempotencyKey || s.json.idempotencyKey.length > 256) {
    throw new Error(`Idempotency key missing or too long for ${s.json.clientName}`);
  }
  if (seenKeys.has(s.json.idempotencyKey)) {
    throw new Error(`Duplicate idempotency key ${s.json.idempotencyKey} — two sends would collapse into one`);
  }
  seenKeys.add(s.json.idempotencyKey);
}

if (sends.length !== list.length) {
  throw new Error(`Built ${sends.length} sends for ${list.length} recipients`);
}

return sends;

function resolveFirstName(text, firstName) {
  return String(text).replace(/\{\{\{FIRST_NAME(\|[^}]*)?\}\}\}/g, (_m, dflt) => firstName || (dflt ? dflt.slice(1) : 'there'));
}

function idempotencyKeyFor(primaryOfferId, r) {
  // Client id when we have one (stable even if the email is later corrected);
  // the email address only for pilot rows with no Client record. Resend allows
  // up to 256 characters; this is ~45.
  const who = r.clientId || String(r.email || '').toLowerCase();
  return `dispatch:${primaryOfferId}:${who}`.replace(/[^A-Za-z0-9:@._+-]/g, '_');
}

/**
 * n8n Code node — "Fail Loudly on Halt"   (Offer Dispatch — Akay, dAYMAj6mZD3hTV4T)
 * Mode: Run Once for All Items
 *
 * SOURCE OF TRUTH: repo .claude/skills/offer-dispatch/n8n/fail-loudly-on-halt.js.
 *
 * A halt IS a failed dispatch attempt, so surface it as one. "Halt — Report
 * Reason" is a NoOp that reported the reason to nobody, which is why a queued
 * offer could simply never go out with no notification anywhere. Throwing here
 * makes the ERROR HANDLER workflow (this workflow's errorWorkflow setting)
 * email ak@akay.ie with the reason.
 *
 * This node must stay LAST on the halt path: Untick Queue on Halt and Write
 * Clear Flag on Halt run first, so the offer is never left stuck ticked. It
 * does need re-queueing by hand once the cause is fixed.
 *
 * Updated 2026-09-02. Only the gate nodes put a `haltReason` on their item.
 * The two halt paths that matter most carried none, so the alert read
 * "no reason recorded" on 21497 and 29315 (approval declined) and on 28559
 * (all 507 sends rejected by Resend with a 401 — the one alert that should
 * have said "check the Resend key"). The reason is now recovered from the
 * node that actually decided the halt: Await Approval on a decline or timeout,
 * Reconcile on a failed or partial send (with the first failure messages, so a
 * 401 reads as a 401), and Composed? / Recipients OK? via their haltReason.
 */
const upstream = $('Halt — Report Reason').all().map((i) => i.json || {});

let reason = upstream.map((u) => u.haltReason).filter(Boolean)[0] || '';
let sentSummary = '';

if (!reason) {
  try {
    const a = $('Await Approval').first().json || {};
    if (a.data && a.data.approved === false) {
      reason = 'Approval DECLINED (or the 3-day approval window expired without a click)' +
        (a.data.respondedAt ? ' at ' + a.data.respondedAt : '') + '. Nothing was sent.';
    }
  } catch (e) { /* approval never ran on this path */ }
}

if (!reason) {
  try {
    const rows = $('Reconcile').all().map((i) => i.json || {});
    const first = rows[0] || {};
    if (first._summary) {
      const failures = rows
        .filter((r) => r['Dispatch Status'] === 'Failed')
        .map((r) => String(r['Notes'] || '').replace(/^Send failed: /, ''));
      const distinct = [...new Set(failures)].slice(0, 3);
      sentSummary = first._summary;
      reason = first._summary +
        (distinct.length ? ' First failure(s): ' + distinct.join(' | ') : '');
      if (failures.some((f) => /401|API key is invalid|unauthor/i.test(f))) {
        reason += ' >>> Resend rejected the API key: every send failed for the same reason, so fix the "Bearer Auth account" credential before re-queueing.';
      }
    }
  } catch (e) { /* Reconcile did not run on this halt path */ }
}

if (!reason) reason = 'no reason recorded';

const offers = new Set();
for (const u of upstream) {
  [u.offerId, u._offerId, ...(Array.isArray(u.bundleOfferIds) ? u.bundleOfferIds : []), ...(Array.isArray(u._offerIds) ? u._offerIds : [])]
    .filter(Boolean).forEach((id) => offers.add(id));
}
if (!offers.size) {
  try {
    const rec = $('Reconcile').first().json || {};
    (rec._offerIds || []).forEach((id) => offers.add(id));
    if (rec._offerId) offers.add(rec._offerId);
  } catch (e) { /* not on this path */ }
}
if (!offers.size) {
  try {
    const br = $('Build Recipients').first().json || {};
    (br.bundleOfferIds || []).forEach((id) => offers.add(id));
    if (br.offerId) offers.add(br.offerId);
  } catch (e) { /* not on this path */ }
}

const sentNothing = !sentSummary || /\b0 sent\b/.test(sentSummary);

throw new Error(
  (sentNothing ? 'Offer dispatch HALTED and sent nothing. ' : 'Offer dispatch ended INCOMPLETE — some emails WERE sent. ') +
  'Reason: ' + reason +
  (offers.size ? '. Offer(s): ' + [...offers].join(', ') : '') +
  '. Queued for Dispatch has been cleared, so re-queue once the cause is fixed.'
);
